create table if not exists public.reviews (id uuid primary key default gen_random_uuid(), reviewer_id uuid not null references public.profiles(id) on delete cascade, reviewed_user_id uuid not null references public.profiles(id) on delete cascade, deal_id uuid not null references public.deals(id) on delete cascade, rating smallint not null check(rating between 1 and 5), comment text, created_at timestamptz not null default now(), check(reviewer_id<>reviewed_user_id), unique(reviewer_id,deal_id));
alter table public.reviews add column if not exists reviewer_id uuid; alter table public.reviews add column if not exists reviewed_user_id uuid; alter table public.reviews add column if not exists deal_id uuid; alter table public.reviews add column if not exists rating smallint; alter table public.reviews add column if not exists comment text; alter table public.reviews add column if not exists created_at timestamptz default now();
